// *** IR Dump After InlineElementals ***
module @_QMrecursion_demo {
  func.func @_QPfactorial(%arg0: !fir.ref<i32> {fir.bindc_name = "n", fir.in}) -> i64 {

    // Result variable r — allocated on the stack
    %r_ref = fir.alloca i64 {bindc_name = "r", uniq_name = "_QFfactorialEr"}

    %n_val = fir.load %arg0 : !fir.ref<i32>
    %c1    = arith.constant 1 : i32

    // if (n <= 1)
    %cond  = arith.cmpi sle, %n_val, %c1 : i32

    fir.if %cond {
      // r = 1
      %one64 = arith.constant 1 : i64
      fir.store %one64 to %r_ref : !fir.ref<i64>
    } else {
      // r = n * factorial(n-1)
      %n64   = fir.convert %n_val : (i32) -> i64

      // Compute n-1
      %n_m1  = arith.subi %n_val, %c1 : i32
      %nm1_ref = fir.alloca i32        // temporary for the argument
      fir.store %n_m1 to %nm1_ref : !fir.ref<i32>

      // Recursive call — standard CALL instruction, no TCO
      %recur = fir.call @_QPfactorial(%nm1_ref) : (!fir.ref<i32>) -> i64

      %prod  = arith.muli %n64, %recur : i64
      fir.store %prod to %r_ref : !fir.ref<i64>
    }

    %result = fir.load %r_ref : !fir.ref<i64>
    return %result : i64
  }
}
