  func.func @_QPfactorial(%arg0: !fir.ref<i32> {fir.bindc_name = "n", fir.in}) -> i64 {

    %n:2 = hlfir.declare %arg0
        {fortran_attrs = #fir.var_attrs<intent_in>, uniq_name = "_QFfactorialEn"}
        : (!fir.ref<i32>) -> (!fir.ref<i32>, !fir.ref<i32>)

    // Result variable — hlfir.declare as local allocatable scalar
    %r_alloc = fir.alloca i64 {bindc_name = "r", uniq_name = "_QFfactorialEr"}
    %r:2 = hlfir.declare %r_alloc
        {uniq_name = "_QFfactorialEr"}
        : (!fir.ref<i64>) -> (!fir.ref<i64>, !fir.ref<i64>)

    %n_val = fir.load %n#0 : !fir.ref<i32>
    %c1_i32 = arith.constant 1 : i32
    %cond   = arith.cmpi sle, %n_val, %c1_i32 : i32

    fir.if %cond {
      %one64 = arith.constant 1 : i64
      hlfir.assign %one64 to %r#0 : i64, !fir.ref<i64>
    } else {
      %n64   = fir.convert %n_val : (i32) -> i64
      %n_m1  = arith.subi %n_val, %c1_i32 : i32
      %nm1   = fir.alloca i32
      fir.store %n_m1 to %nm1 : !fir.ref<i32>

      // Recursive self-call — note: no 'tail' attribute
      %recur = fir.call @_QPfactorial(%nm1) : (!fir.ref<i32>) -> i64

      %prod  = arith.muli %n64, %recur : i64
      hlfir.assign %prod to %r#0 : i64, !fir.ref<i64>
    }

    %result = fir.load %r#0 : !fir.ref<i64>
    return %result : i64
  }
